291	
292	    /** Adds an OPEN claim split off {@code from}: its date and note, the given number, opened by the user
293	     *  and due by {@code dueBy}, listed as its person's newest claim. */
294	    public Claim addSplit(Claim from, BigDecimal amount, String number, String openedBy, LocalDate dueBy) {
295	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
296	        jdbc.update(con -> {
297	            PreparedStatement ps = con.prepareStatement(
298	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, number, opened_by, due_by, split_from) "
299	                            + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
300	                    new String[] { "ID" });
301	            ps.setString(1, from.getSheetId());
302	            ps.setLong(2, from.getPersonId());
303	            ps.setBigDecimal(3, amount);
304	            ps.setDate(4, Date.valueOf(from.getDate()));
305	            ps.setString(5, from.getNote());
306	            ps.setString(6, ClaimStatus.OPEN.name());
307	            ps.setString(7, number);
308	            ps.setString(8, openedBy);
309	            ps.setDate(9, Date.valueOf(dueBy));
310	            ps.setString(10, from.getNumber());
311	            return ps;
312	        }, keys);
313	        Claim added = new Claim(keys.getKey().longValue(), from.getSheetId(), from.getPersonId(), amount, from.getDate(),
314	                from.getNote(), ClaimStatus.OPEN, number, null, openedBy, false, null, null, dueBy);
315	        added.setSplitFrom(from.getNumber());
316	        return added;
317	    }
318	
319	    /** Raises the stored DRAFT, OPEN or PENDING claim's proofs count by one; false when it is no longer one of
320	     *  those (another user moved it on). */
321	    public boolean addProof(Claim claim) {
322	        boolean added = jdbc.update("UPDATE claim SET proofs = proofs + 1 WHERE sheet_id = ? AND id = ? AND status IN (?, ?, ?)",
323	                claim.getSheetId(), claim.getId(), ClaimStatus.DRAFT.name(), ClaimStatus.OPEN.name(),
324	                ClaimStatus.PENDING.name()) == 1;
325	        if (added) {
326	            claim.setProofs(jdbc.queryForObject("SELECT proofs FROM claim WHERE sheet_id = ? AND id = ?", Integer.class,
327	                    claim.getSheetId(), claim.getId()));
328	        }
329	        return added;
330	    }
331	
332	    /** Moves the stored DRAFT, OPEN or PENDING claim to the person, unbound from any statement figure and
333	     *  listed as their newest claim; false when it is no longer one of those (another user moved it on). */
334	    public boolean reassign(Claim claim, long personId) {
335	        boolean moved = jdbc.update("UPDATE claim SET person_id = ?, stated = FALSE, stated_due = NULL, stated_na = FALSE, "
336	                + "listed = NEXT VALUE FOR claim_listed_seq WHERE sheet_id = ? AND id = ? AND status IN (?, ?, ?)",
337	                personId, claim.getSheetId(), claim.getId(), ClaimStatus.DRAFT.name(), ClaimStatus.OPEN.name(),
338	                ClaimStatus.PENDING.name()) == 1;
339	        if (moved) {
340	            claim.setPersonId(personId);
341	            claim.setStated(false);
342	            claim.setStatedDue(null);
343	            claim.setStatedNa(false);
344	        }
345	        return moved;
346	    }
347	
348	    /** Moves the stored claim from {@code from} to {@code to}, locking its row until the transaction
349	     *  ends; false when it is no longer {@code from} (another user moved it first). */
350	    public boolean move(Claim claim, ClaimStatus from, ClaimStatus to) {
351	        return jdbc.update("UPDATE claim SET status = ? WHERE sheet_id = ? AND id = ? AND status = ?", to.name(),
352	                claim.getSheetId(), claim.getId(), from.name()) == 1;
353	    }
354	
355	    /** Takes the next claim number on the sheet: 1, then 2, and so on. The sheet's counter row stays
356	     *  locked until the transaction ends, so a number is never given twice, and is not used up if
357	     *  the transaction rolls back. */
358	    public long nextNumber(String sheetId) {
359	        try {
360	            jdbc.update("INSERT INTO claim_number (sheet_id, last_number) SELECT ?, 0 FROM DUAL "
361	                    + "WHERE NOT EXISTS (SELECT 1 FROM claim_number WHERE sheet_id = ?)", sheetId, sheetId);
362	        } catch (DataAccessException e) {
363	            // another transaction added the sheet's counter first
364	        }
365	        jdbc.update("UPDATE claim_number SET last_number = last_number + 1 WHERE sheet_id = ?", sheetId);
366	        return jdbc.queryForObject("SELECT last_number FROM claim_number WHERE sheet_id = ?", Long.class, sheetId);
367	    }
368	
369	    /** Takes the next number in one of the sheet's per-period sequences: 1, then 2, and so on, locked
370	     *  as {@link #nextNumber(String)} is. */
371	    public long nextNumber(String sheetId, String sequence) {
372	        try {
373	            jdbc.update("INSERT INTO claim_period_number (sheet_id, sequence, last_number) SELECT ?, ?, 0 FROM DUAL "
374	                    + "WHERE NOT EXISTS (SELECT 1 FROM claim_period_number WHERE sheet_id = ? AND sequence = ?)",
375	                    sheetId, sequence, sheetId, sequence);
376	        } catch (DataAccessException e) {
377	            // another transaction added the sequence's counter first
378	        }
379	        jdbc.update("UPDATE claim_period_number SET last_number = last_number + 1 WHERE sheet_id = ? AND sequence = ?",
380	                sheetId, sequence);
381	        return jdbc.queryForObject("SELECT last_number FROM claim_period_number WHERE sheet_id = ? AND sequence = ?",
382	                Long.class, sheetId, sequence);
383	    }
384	}
