387	import java.math.BigDecimal;
388	import java.time.LocalDate;
389	import java.util.LinkedHashMap;
390	import java.util.List;
391	import java.util.Map;
392	import net.officefloor.hq.app.history.History;
393	import org.springframework.jdbc.core.JdbcTemplate;
394	import org.springframework.jdbc.core.RowMapper;
395	import org.springframework.stereotype.Repository;
396	
397	/** The periods on each sheet. */
398	@Repository
399	public class PeriodStore {
400	
401	    private final RowMapper<PeriodResponse> ROW = (rs, i) -> PeriodResponse.of(rs.getString("name"),
402	            rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class),
403	            rs.getBoolean("closed"), rs.getBigDecimal("closed_total"),
404	            rs.getBoolean("closed") || rs.getBoolean("soft") ? personTotals(rs.getString("sheet_id"), rs.getString("name"))
405	                    : Map.of(),
406	            rs.getBoolean("soft"));
407	
408	    private final JdbcTemplate jdbc;
409	
410	    public PeriodStore(JdbcTemplate jdbc) {
411	        this.jdbc = jdbc;
412	    }
413	
414	    /** Every period on the sheet, by from-date. */
415	    public List<PeriodResponse> list(String sheetId) {
416	        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? ORDER BY from_date", ROW, sheetId);
417	    }
418	
419	    /** Every period on the sheet as the periods and their fixed figures stood at the end of the date (see
420	     *  {@link History}), by from-date. */
421	    public List<PeriodResponse> listAsOf(String sheetId, LocalDate date) {
422	        String totals = History.asOf("period_person_total", "sheet_id, period_name, person_id", date);
423	        return jdbc.query("SELECT * FROM " + History.asOf("period", "id", date) + " WHERE sheet_id = ? ORDER BY from_date",
424	                (rs, i) -> PeriodResponse.of(rs.getString("name"), rs.getObject("from_date", LocalDate.class),
425	                        rs.getObject("to_date", LocalDate.class), rs.getBoolean("closed"),
426	                        rs.getBigDecimal("closed_total"),
427	                        rs.getBoolean("closed") || rs.getBoolean("soft")
428	                                ? personTotals(rs.getString("sheet_id"), rs.getString("name"), totals)
429	                                : Map.of(),
430	                        rs.getBoolean("soft")),
431	                sheetId);
432	    }
433	
434	    /** The period on the sheet with this name, or null when there is none. */
435	    public PeriodResponse find(String sheetId, String name) {
436	        List<PeriodResponse> found = jdbc.query("SELECT * FROM period WHERE sheet_id = ? AND name = ?", ROW, sheetId,
437	                name);
438	        return found.isEmpty() ? null : found.get(0);
439	    }
440	
441	    /** The closed period on the sheet whose dates contain the date, or null when none does. */
442	    public PeriodResponse closedOn(String sheetId, LocalDate date) {
443	        List<PeriodResponse> found = jdbc.query(
444	                "SELECT * FROM period WHERE sheet_id = ? AND closed AND from_date <= ? AND to_date >= ?", ROW, sheetId,
445	                date, date);
446	        return found.isEmpty() ? null : found.get(0);
447	    }
448	
449	    /** Whether the period on the sheet whose dates contain the date is soft-closed. */
450	    public boolean softOn(String sheetId, LocalDate date) {
451	        Integer n = jdbc.queryForObject(
452	                "SELECT COUNT(*) FROM period WHERE sheet_id = ? AND soft AND from_date <= ? AND to_date >= ?",
453	                Integer.class, sheetId, date, date);
454	        return n != null && n > 0;
455	    }
456	
457	    /** The period on the sheet whose dates contain the date, or null when none does. */
458	    public PeriodResponse on(String sheetId, LocalDate date) {
459	        List<PeriodResponse> found = jdbc.query(
460	                "SELECT * FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?", ROW, sheetId, date, date);
461	        return found.isEmpty() ? null : found.get(0);
462	    }
463	
464	    /** Whether a period on the sheet has this name, ignoring case. */
465	    public boolean nameTaken(String sheetId, String name) {
466	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND LOWER(name) = LOWER(?)",
467	                Integer.class, sheetId, name);
468	        return n != null && n > 0;
469	    }
470	
471	    /** Whether a period on the sheet shares a day with from..to (inclusive). */
472	    public boolean overlaps(String sheetId, LocalDate from, LocalDate to) {
473	        Integer n = jdbc.queryForObject(
474	                "SELECT COUNT(*) FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?", Integer.class,
475	                sheetId, to, from);
476	        return n != null && n > 0;
477	    }
478	
479	    public void add(String sheetId, PeriodInput period) {
480	        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)", sheetId,
481	                period.name(), period.from(), period.to());
482	    }
483	
484	    /** Each person's due-total fixed when the period was closed, by person id. */
485	    private Map<Long, BigDecimal> personTotals(String sheetId, String name) {
486	        return personTotals(sheetId, name, "period_person_total");
487	    }
488	
489	    private Map<Long, BigDecimal> personTotals(String sheetId, String name, String table) {
490	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
491	        jdbc.query("SELECT person_id, total FROM " + table + " WHERE sheet_id = ? AND period_name = ? ORDER BY person_id",
492	                rs -> {
493	                    totals.put(rs.getLong("person_id"), rs.getBigDecimal("total"));
494	                }, sheetId, name);
495	        return totals;
496	    }
497	
498	    /** Fixes each person's due-total in the period as it is when it is closed. */
499	    public void fixPersonTotals(String sheetId, String name, Map<Long, BigDecimal> totals) {
500	        totals.forEach((personId, total) -> jdbc.update(
501	                "INSERT INTO period_person_total (sheet_id, period_name, person_id, total) VALUES (?, ?, ?, ?)",
502	                sheetId, name, personId, total));
503	    }
504	
505	    /** Drops each person's due-total fixed in the period (as a soft close fixed them, before they are fixed afresh). */
506	    public void dropPersonTotals(String sheetId, String name) {
507	        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?", sheetId, name);
508	    }
509	
510	    /** Closes the open (or soft-closed) period with its due-total fixed; false when it is already closed
511	     *  (another user closed it first). */
512	    public boolean close(String sheetId, String name, BigDecimal total) {
513	        return jdbc.update("UPDATE period SET closed = TRUE, soft = FALSE, closed_total = ? "
514	                + "WHERE sheet_id = ? AND name = ? AND NOT closed", total, sheetId, name) == 1;
515	    }
516	
517	    /** Soft-closes the open period with its due-total fixed; false when it is already closed or soft-closed. */
518	    public boolean softClose(String sheetId, String name, BigDecimal total) {
519	        return jdbc.update("UPDATE period SET soft = TRUE, closed_total = ? "
520	                + "WHERE sheet_id = ? AND name = ? AND NOT closed AND NOT soft", total, sheetId, name) == 1;
521	    }
522	
523	    /** Reopens the closed or soft-closed period, dropping its fixed due-total; false when it is neither
524	     *  (another user reopened it first). */
525	    public boolean reopen(String sheetId, String name) {
526	        dropPersonTotals(sheetId, name);
527	        return jdbc.update("UPDATE period SET closed = FALSE, soft = FALSE, closed_total = NULL "
528	                + "WHERE sheet_id = ? AND name = ? AND (closed OR soft)", sheetId, name) == 1;
529	    }
530	}
