539	/** The number a claim receives when opened. While the sheet's period-numbering-from is set and the
540	 *  sheet's today is on or after it, the claim is numbered within the period its date falls in,
541	 *  <period name>-<n> counting from 1 in each period, or X-<n> in its own sequence when it falls in
542	 *  none. Otherwise it takes the sheet's next sheet-wide number (1, 2, ...), which carries on from
543	 *  where it left off. */
544	public final class Numbering {
545	
546	    /** The sequence of claims dated in no period. */
547	    private static final String NO_PERIOD = "X";
548	
549	    private Numbering() {
550	    }
551	
552	    public static String next(String sheetId, LocalDate claimDate, ClaimStore claims, SettingStore settings,
553	            SheetStore sheets, PeriodStore periods) {
554	        LocalDate from = settings.periodNumberingFrom(sheetId);
555	        if (from == null || sheets.today(sheetId).isBefore(from)) {
556	            return String.valueOf(claims.nextNumber(sheetId));
557	        }
558	        PeriodResponse period = periods.on(sheetId, claimDate);
559	        if (period == null) {
560	            return NO_PERIOD + "-" + claims.nextNumber(sheetId, NO_PERIOD);
561	        }
562	        return period.name() + "-" + claims.nextNumber(sheetId, "P:" + period.name());
563	    }
564	}
565	package net.officefloor.hq.app.claim;
566	
567	import java.math.BigDecimal;
568	import java.time.LocalDate;
569	import java.time.temporal.ChronoUnit;
570	import java.util.function.Function;
571	import net.officefloor.hq.app.setting.SettingStore;
572	import net.officefloor.hq.app.sheet.SheetStore;
573	
574	/** What a sheet's late charge follows: each claim's due-by (fixed when it was added), the sheet's late
575	 *  percent in force on each date and its today; and the sheet's floor in force on each claim's date. An overdue claim (OPEN or PENDING, not deferred, due-by before today) gains, for every full 30 days it is
576	 *  overdue, the late percent in force on that boundary (its due-by plus 30, 60, 90 ... days) of its figure, rounded as the
577	 *  sheet's {@link Rounding} has the claim, the charges added up (a boundary at 0.00 adds nothing). The charge is never bound by a
578	 *  statement; settling freezes it into the settled due. The floor is applied last: a live due is at least the floor
579	 *  in force on the claim's date (none for a correction). */
580	public record Lateness(Function<LocalDate, BigDecimal> latePcts, Function<LocalDate, BigDecimal> floors,
581	        LocalDate today, Rounding rounding) {
582	
583	    /** The days in each step of the late charge. */
584	    private static final int PERIOD_DAYS = 30;
585	
586	    public static Lateness of(String sheetId, SettingStore settings, SheetStore sheets, ClaimStore claims) {
587	        return new Lateness(settings.latePcts(sheetId), settings.floors(sheetId), sheets.today(sheetId),
588	                Rounding.of(sheetId, settings, sheets, claims));
589	    }
590	
591	    /** The late charge on a claim whose figure (bound, else the rate figure, never floored) is {@code figure}; none on
592	     *  a correction. */
593	    public BigDecimal charge(Claim claim, BigDecimal figure) {
594	        if (figure == null || !claim.getStatus().isOpen() || today == null || claim.isCorrection()
595	                || claim.isDeferredOn(today)) {
596	            return BigDecimal.ZERO.setScale(2);
597	        }
598	        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), today);
599	        long periods = overdue <= 0 ? 0 : overdue / PERIOD_DAYS;
600	        BigDecimal total = BigDecimal.ZERO.setScale(2);
601	        for (long n = 1; n <= periods; n++) {
602	            BigDecimal pct = latePcts.apply(claim.getDueBy().plusDays(n * PERIOD_DAYS));
603	            total = total.add(ClaimFigure.of(figure, pct, rounding.mode(claim)));
604	        }
605	        return total;
606	    }
607	
608	    /** The floor in force on the claim's date. */
609	    public BigDecimal floor(Claim claim) {
610	        return floors.apply(claim.getDate());
611	    }
612	
613	    /** The claim's due now: its settled due, else the greater of its floor and its figure plus the late
614	     *  charge (a correction has no floor and no charge). */
615	    public BigDecimal due(Claim claim, BigDecimal pct) {
616	        return dueOf(claim, ClaimFigure.of(claim, pct, rounding));
617	    }
618	
619	    /** The claim's due now, given its figure (see {@link ClaimFigure}). */
620	    public BigDecimal dueOf(Claim claim, BigDecimal figure) {
621	        if (figure == null || claim.getSettledDue() != null) {
622	            return figure;
623	        }
624	        BigDecimal charged = figure.add(charge(claim, figure));
625	        return claim.isCorrection() ? charged : ClaimFigure.floored(charged, floor(claim));
626	    }
627	}
