package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Retirement;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;

/** The claim form's add, step by step, for a change that adds several claims at once (a paste). */
public final class ClaimAdding {
    private ClaimAdding() {
    }

    /** The claim form's rules on a claim typed for the person, before anything is stored: the claim as
     *  it would be stored. */
    public static ClaimInput check(String sheetId, Person person, ClaimRequest request, SettingStore settings,
            PeriodStore periods, ClaimStore claims) throws InvalidSheetException {
        ClaimInput input = ValidateClaim.check(sheetId, request, settings);
        CheckClaimPeriod.refuseClosed(periods, sheetId, input.date());
        Retirement.refuseClaimDate(person, input.date());
        CheckCorrection.refuseUnsettled(claims, sheetId, person.getId(), input);
        return input;
    }

    /** Stores the checked claim as a DRAFT and records it as CLAIM_ADDED (and LATE_ENTRY for a late entry), then how it moved the figures. */
    public static Claim add(ClaimInput input, Person person, ClaimStore store, SettingStore settings,
            ClaimLogStore log, PeriodStore periods, RollupService rollups, Audit audit) {
        var before = rollups.snapshot(person.getSheetId());
        Claim claim = SaveClaimAdded.add(input, person, store, settings, log, periods);
        AuditClaimAdded.record(input, person, claim, before, audit, rollups);
        return claim;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds the claim (a late entry when the period its date falls in is soft-closed), due by its date plus its person's own terms (else the terms of their grade in force on
 *  that date, else the sheet's terms in force then), fixed now, and logs it as DRAFT by the user at its due then. */
public class SaveClaimAdded {
    public void save(@Val ClaimInput input, @Val Person person, ClaimStore store, SettingStore settings,
            ClaimLogStore log, PeriodStore periods, Out<Claim> claim) {
        claim.set(add(input, person, store, settings, log, periods));
    }

    static Claim add(ClaimInput input, Person person, ClaimStore store, SettingStore settings, ClaimLogStore log,
            PeriodStore periods) {
        int terms = termsOf(person, input.date(), settings);
        Claim added = store.add(person.getSheetId(), person.getId(), input.amount(), input.date(), input.note(),
                input.corrects(), input.date().plusDays(terms));
        if (periods.softOn(person.getSheetId(), input.date())) {
            store.markLateEntry(added);
        }
        log.record(added, input.user());
        return added;
    }

    /** The terms a claim of the person dated {@code date} is due by: their own, else their grade's in force
     *  on the date, else the sheet's then. */
    static int termsOf(Person person, java.time.LocalDate date, SettingStore settings) {
        return person.getTerms() != null ? person.getTerms()
                : settings.terms(person.getSheetId(), person.gradeOn(date), date);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.Objects;
import net.officefloor.hq.app.period.PeriodResponse;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Stores the claim's new date, keeping its due-by and any figure a statement bound it to. While the
 *  sheet numbers by period and the new date falls in another period (or none), the claim takes the
 *  next number of its new period's sequence; its old number is not given again. */
public class ApplyRedate {
    public void apply(@Val RedateInput input, @Val Claim claim, ClaimStore store, SettingStore settings,
            SheetStore sheets, PeriodStore periods, Out<Redating> redating) throws InvalidSheetException {
        LocalDate old = claim.getDate();
        String number = claim.getNumber();
        LocalDate from = settings.periodNumberingFrom(claim.getSheetId());
        if (number != null && from != null && !sheets.today(claim.getSheetId()).isBefore(from)
                && !Objects.equals(periodName(periods, claim.getSheetId(), old),
                        periodName(periods, claim.getSheetId(), input.date()))) {
            number = Numbering.next(claim.getSheetId(), input.date(), store, settings, sheets, periods);
        }
        if (!store.redate(claim, input.date(), number)) {
            throw new InvalidSheetException("The claim has moved on");
        }
        redating.set(new Redating(old, input.date()));
    }

    private static String periodName(PeriodStore periods, String sheetId, LocalDate date) {
        PeriodResponse period = periods.on(sheetId, date);
        return period == null ? null : period.name();
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.person.Retirement;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses a claim's re-dating unless a steward re-dates an OPEN or PENDING claim to a date outside
 *  any closed period and not after the date its person is retired from. */
public class CheckRedate {
    public void check(@Val RedateInput input, @Val Claim claim, RoleStore roles, PersonStore people,
            PeriodStore periods) throws InvalidSheetException {
        if (roles.find(claim.getSheetId(), input.user()) != Role.STEWARD) {
            throw new InvalidSheetException("Only a steward may re-date a claim");
        }
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new InvalidSheetException("A " + claim.getStatus() + " claim cannot be re-dated");
        }
        CheckClaimPeriod.refuseClosed(periods, claim.getSheetId(), input.date());
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        if (person != null) {
            Retirement.refuseClaimDate(person, input.date());
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Splits the amount off the OPEN claim, which keeps the rest unbound from any statement figure, into a new
 *  OPEN claim of the same date and note, numbered next (see {@link Numbering}), opened by the user, due by
 *  its date plus its person's own terms (else their grade's in force on that date, else the sheet's then), fixed
 *  now, and logged as OPEN by the user. Refused when another user moved the claim on first. */
public class ApplySplit {
    public void apply(@Val SplitInput input, @Val Claim claim, ClaimStore store, PersonStore people, SettingStore settings,
            SheetStore sheets, PeriodStore periods, ClaimLogStore log, Out<Split> split) throws InvalidSheetException {
        if (!store.shrink(claim, claim.getAmount().subtract(input.amount()))) {
            throw new InvalidSheetException("Only an OPEN claim can be split");
        }
        String sheetId = claim.getSheetId();
        Person person = people.find(sheetId, claim.getPersonId());
        int terms = SaveClaimAdded.termsOf(person, claim.getDate(), settings);
        String number = Numbering.next(sheetId, claim.getDate(), store, settings, sheets, periods);
        Claim into = store.addSplit(claim, input.amount(), number, input.user(), claim.getDate().plusDays(terms));
        log.record(into, input.user());
        split.set(new Split(into));
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Opens each selected claim that can be opened, in list order: its people in the order they were
 *  added, a person's claims newest first. Each is opened as a single open would be (its next
 *  number, opened-by the user) and recorded as CLAIM_OPENED, then how it moved the sheet's figures.
 *  A claim that is not on the sheet, is not a DRAFT, or is dated in a closed period, or has an empty note while its due is above the
 *  note threshold in force on its date, and every claim when
 *  the sheet is archived or the sheet's permission matrix does not allow the user's role to open, is refused and
 *  left as it is. */
public class OpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpenInput input, ClaimStore store,
            PersonStore people, PeriodStore periods, SettingStore settings, SheetStore sheets, RoleStore roles, RateStore rates, ClaimLogStore log, RollupService rollups, Audit audit, Out<BulkOpenResult> result) {
        String sheet = sheetId.trim();
        Map<Long, Integer> personOrder = new HashMap<>();
        Map<Long, Person> persons = new HashMap<>();
        for (Person person : people.list(sheet)) {
            personOrder.put(person.getId(), personOrder.size());
            persons.put(person.getId(), person);
        }
        int refused = 0;
        List<Claim> selected = new ArrayList<>();
        for (Long id : input.claimIds()) {
            Claim claim = id == null ? null : store.find(sheet, id);
            if (claim == null) {
                refused++;
            } else {
                selected.add(claim);
            }
        }
        selected.sort(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                .thenComparing(Comparator.comparingLong(Claim::getId).reversed()));
        boolean permitted = !sheets.archived(sheet) && settings.allows(sheet, "open", roles.find(sheet, input.user()));
        int opened = 0;
        for (Claim claim : selected) {
            if (!permitted || claim.getStatus() != ClaimStatus.DRAFT || closed(periods, claim)
                    || unnoted(claim, settings, people, rates, sheets, store)) {
                refused++;
                continue;
            }
            Rollup before = rollups.snapshot(sheet);
            if (!store.move(claim, claim.getStatus(), ClaimStatus.OPEN)) {
                refused++;
                continue;
            }
            claim.setStatus(ClaimStatus.OPEN);
            claim.setNumber(Numbering.next(sheet, claim.getDate(), store, settings, sheets, periods));
            claim.setOpenedBy(input.user());
            store.save(claim);
            log.record(claim, input.user());
            Person person = persons.get(claim.getPersonId());
            ClaimResponse shown = ClaimResponse.from(claim);
            audit.record(ClaimStatus.OPEN.event() + " sheet=" + sheet + " by=" + input.user() + " person="
                    + (person == null ? "" : person.getName()) + " amount=" + shown.amount() + " date=" + shown.date()
                    + " number=" + claim.getNumber());
            rollups.record(sheet, input.user(), before);
            opened++;
        }
        result.set(new BulkOpenResult(opened, refused));
    }

    private static boolean unnoted(Claim claim, SettingStore settings, PersonStore people, RateStore rates,
            SheetStore sheets, ClaimStore store) {
        try {
            CheckProofs.refuseUnnoted(claim, settings, people, rates, sheets, store);
            return false;
        } catch (InvalidSheetException e) {
            return true;
        }
    }

    private static boolean closed(PeriodStore periods, Claim claim) {
        try {
            CheckClaimPeriod.refuseClosed(periods, claim.getSheetId(), claim.getDate());
            return false;
        } catch (InvalidSheetException e) {
            return true;
        }
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaim {
    /** A number with up to two decimals; negative for a correction. */
    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
    /** A claim number: the sheet-wide 1, 2, ... or <period>-<n> / X-<n>. */
    private static final Pattern NUMBER = Pattern.compile("\\S{1,255}");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ClaimRequest request,
            SettingStore settings, Out<ClaimInput> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        body.set(check(sheetId, request, settings));
    }

    /** The claim form's rules on a typed claim, before anything is stored: the claim as it would be stored
     *  (a blank date is the entry date while it is set, else the sheet's today). */
    static ClaimInput check(String sheetId, ClaimRequest request, SettingStore settings) throws InvalidSheetException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidSheetException("The amount must be a number with up to two decimals");
        }
        String dateText = request.date() == null ? "" : request.date().trim();
        LocalDate date;
        try {
            date = dateText.isEmpty() ? settings.claimDate(sheetId.trim()) : LocalDate.parse(dateText);
        } catch (DateTimeParseException e) {
            throw new InvalidSheetException("Not a date: " + dateText);
        }
        String note = request.note() == null ? "" : request.note().trim();
        BigDecimal value = new BigDecimal(amount).setScale(2);
        String correctsText = request.corrects() == null ? "" : request.corrects().trim();
        String corrects = null;
        if (value.signum() < 0) {
            if (!NUMBER.matcher(correctsText).matches()) {
                throw new InvalidSheetException("A negative amount must name the number of the settled claim it corrects");
            }
            corrects = correctsText;
        } else if (!correctsText.isEmpty()) {
            throw new InvalidSheetException("Only a negative amount corrects a claim");
        }
        return new ClaimInput(value, date, note, request.user(), corrects);
    }
}
