package net.officefloor.hq.app.quick;

import java.math.BigDecimal;
import java.util.regex.Pattern;
import net.officefloor.hq.app.claim.ClaimInput;
import net.officefloor.hq.app.person.PersonRequest;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Applies the person form's and the claim form's rules to a quick add, before anything is stored:
 * the name is required (and trimmed), the amount is 0.00 or more with up to two decimals. Publishes
 * the person as it would be added (grade A) and the draft claim (the entry date while it is set, else the sheet's today, an empty note).
 */
public class ValidateQuickAdd {
    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody QuickAddRequest request,
            SettingStore settings, Out<PersonRequest> person, Out<ClaimInput> claim, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        if (request == null || request.name() == null || request.name().trim().isEmpty()) {
            throw new InvalidSheetException("A name is required");
        }
        String amount = request.amount() == null ? "" : request.amount().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidSheetException("The amount must be a number of 0.00 or more with up to two decimals");
        }
        person.set(new PersonRequest(request.name().trim(), "A", null, request.user(), null, null));
        claim.set(new ClaimInput(new BigDecimal(amount).setScale(2), settings.claimDate(sheetId.trim()), "",
                request.user()));
    }
}
package net.officefloor.hq.app.quick;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimInput;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRequest;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.person.Retirement;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * The person on the sheet with the quick add's name (ignoring case); when there is none, adds them
 * as the person form would, recording PERSON_ADDED and how it moved the figures. Runs only once the
 * claim has passed every check, so a refused quick add leaves no person behind. Refuses the claim when
 * the person found is retired from a date before it.
 */
public class FindOrAddPerson {
    public void find(@PathVariable("sheetId") String sheetId, @Val PersonRequest request, @Val ClaimInput claim,
            PersonStore store, Audit audit, RollupService rollups, Out<Person> personOut) throws InvalidSheetException {
        String sheet = sheetId.trim();
        Person person = store.findByName(sheet, request.name());
        if (person != null) {
            Retirement.refuseClaimDate(person, claim.date());
        } else {
            Rollup before = rollups.snapshot(sheet);
            person = store.add(sheet, request.name(), request.grade());
            audit.record("PERSON_ADDED sheet=" + sheet + " by=" + request.user() + " name=" + person.getName()
                    + " grade=" + request.grade());
            rollups.record(sheet, request.user(), before);
        }
        personOut.set(person);
    }
}
 * Checks every pasted line with exactly the claim form's rules before anything is stored: the name
 * must be on the sheet (ignoring case and the spaces around it), the amount a number with up to two
 * decimals (a negative one names no claim it corrects, so is refused), the date (blank for the
 * entry date while it is set, else the sheet's today) in no closed period and not after the person is retired from. The note is the rest
 * of the line, commas and all. Blank lines are skipped; a paste with no line is refused.
 */
public class ValidatePaste {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PasteRequest request,
            SettingStore settings, PersonStore people, PeriodStore periods, ClaimStore claims, Out<PasteInput> pasted, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        String sheet = sheetId.trim();
        String text = request == null || request.text() == null ? "" : request.text();
        List<PastedClaim> pastedClaims = new ArrayList<>();
        String[] lines = text.split("\\r?\\n");
        for (int i = 0; i < lines.length; i++) {
            String line = lines[i];
            if (line.trim().isEmpty()) {
                continue;
            }
            String[] fields = line.split(",", 4);
            if (fields.length < 2) {
                throw new InvalidSheetException("Line " + (i + 1) + " must be name,amount,date,note");
            }
            try {
                Person person = people.findByName(sheet, fields[0]);
                if (person == null) {
                    throw new InvalidSheetException("No such person: " + fields[0].trim());
                }
                ClaimInput claim = ClaimAdding.check(sheet, person, new ClaimRequest(fields[1],
                        fields.length > 2 ? fields[2] : "", fields.length > 3 ? fields[3] : "", request.user(), ""),
                        settings, periods, claims);
                pastedClaims.add(new PastedClaim(person, claim));
            } catch (InvalidSheetException e) {
                throw new InvalidSheetException("Line " + (i + 1) + ": " + e.getMessage());
            }
        }
        if (pastedClaims.isEmpty()) {
            throw new InvalidSheetException("Paste at least one line of name,amount,date,note");
        }
        pasted.set(new PasteInput(pastedClaims));
    }
}

